package com.fuelflex.platform.operations.service;
import java.math.*;import java.time.OffsetDateTime;import java.util.*;import java.util.function.Function;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
import com.fuelflex.platform.common.exception.ConflictException;import com.fuelflex.platform.operations.entity.*;import com.fuelflex.platform.operations.repository.*;import com.fuelflex.platform.reception.repository.ReceptionStockBalanceRepository;import com.fuelflex.platform.sale.repository.SaleStockMovementRepository;import com.fuelflex.platform.tank.entity.Tank;import com.fuelflex.platform.tank.repository.TankRepository;import com.fuelflex.platform.user.entity.User;import lombok.RequiredArgsConstructor;
@Service @RequiredArgsConstructor @Transactional public class OperationalDayClosingService{
 private final PumpShiftAssignmentRepository shifts;private final ShiftReconciliationRepository reconciliations;private final TankGaugeReadingRepository gauges;private final TankRepository tanks;private final DailyExpenseRepository expenses;private final ReceptionStockBalanceRepository inbound;private final SaleStockMovementRepository outbound;private final MeteredStockMovementRepository meteredStock;private final TankReturnSourceMovementRepository returnSourceStock;private final TankReturnStockMovementRepository returnedStock;private final OperationalDaySummaryRepository summaries;private final SupervisorOperationalNotifier notifier;
 public OperationalDaySummary prepare(OperationalDay day,User actor){long open=shifts.countByOperationalDayIdAndStatus(day.getId(),OperationalStatus.OPEN);if(open>0)throw new ConflictException("Impossible de clôturer la journée : "+open+" affectation(s) restent ouvertes.");long shiftCount=shifts.countByOperationalDayId(day.getId());if(reconciliations.countByShiftAssignmentOperationalDayId(day.getId())!=shiftCount)throw new ConflictException("Tous les rapprochements doivent être calculés avant la clôture.");List<Tank> active=tanks.findByDepotStationIdAndActiveTrueOrderByDisplayOrderAscNameAsc(day.getStation().getId());List<TankGaugeReading> readings=gauges.findByOperationalDayIdOrderByTankNameAsc(day.getId());Set<UUID> gauged=new HashSet<>();readings.forEach(g->gauged.add(g.getTank().getId()));List<String> missing=active.stream().filter(t->!gauged.contains(t.getId())).map(Tank::getName).toList();if(!missing.isEmpty())throw new ConflictException("Jauges manquantes pour les cuves: "+String.join(", ",missing)+".");readings.forEach(g->{BigDecimal current=stock(g.getTank().getId());g.setTheoreticalStock(current);g.setStockVariance(s(g.getPhysicalStock().subtract(current)));});gauges.saveAll(readings);
  List<ShiftReconciliation> recs=reconciliations.findByShiftAssignmentOperationalDayIdOrderByShiftAssignmentOpenedAtAsc(day.getId());BigDecimal cashV=sum(recs,ShiftReconciliation::getCashVolume),creditV=sum(recs,ShiftReconciliation::getCreditVolume),cashA=sum(recs,ShiftReconciliation::getCashAmount),creditA=sum(recs,ShiftReconciliation::getCreditAmount),metered=sum(recs,ShiftReconciliation::getMeteredVolume),returned=sum(recs,ShiftReconciliation::getTankReturnVolume);BigDecimal sold=s(cashV.add(creditV)),accounted=s(sold.add(returned)),expense=s(expenses.sumByDayId(day.getId())),theoretical=s(readings.stream().map(TankGaugeReading::getTheoreticalStock).reduce(BigDecimal.ZERO,BigDecimal::add)),physical=s(readings.stream().map(TankGaugeReading::getPhysicalStock).reduce(BigDecimal.ZERO,BigDecimal::add));OperationalDaySummary summary=new OperationalDaySummary();summary.setOperationalDay(day);summary.setCashVolume(cashV);summary.setCashAmount(cashA);summary.setCreditVolume(creditV);summary.setCreditAmount(creditA);summary.setMeteredVolume(metered);summary.setSoldVolume(sold);summary.setTankReturnVolume(returned);summary.setAccountedVolume(accounted);summary.setVolumeVariance(s(metered.subtract(accounted)));summary.setExpenseAmount(expense);summary.setExpectedCash(cashA);summary.setExpectedNetCash(s(cashA.subtract(expense)));summary.setTheoreticalStock(theoretical);summary.setPhysicalStock(physical);summary.setStockVariance(s(physical.subtract(theoretical)));summary.setClosedBy(actor);summary.setClosedAt(OffsetDateTime.now());summary=summaries.save(summary);notifier.inform(actor,day.getStation(),"OPERATIONAL_DAY_CLOSED","OPERATIONAL_DAY",day.getId());return summary;}
 private BigDecimal stock(UUID tankId){BigDecimal v=s(inbound.sumInboundByTankId(tankId)).subtract(s(outbound.sumOutboundByTankId(tankId))).subtract(s(meteredStock.sumOutboundByTankId(tankId))).subtract(s(returnSourceStock.sumOpenOutboundByTankId(tankId))).add(s(returnedStock.sumInboundByTankId(tankId)));if(v.signum()<0)throw new ConflictException("Le stock théorique d’une cuve est négatif.");return s(v);}private BigDecimal sum(List<ShiftReconciliation> values,Function<ShiftReconciliation,BigDecimal> field){return s(values.stream().map(field).reduce(BigDecimal.ZERO,BigDecimal::add));}private BigDecimal s(BigDecimal v){return(v==null?BigDecimal.ZERO:v).setScale(3,RoundingMode.UNNECESSARY);}
}
